import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"TraeCode tutorial","description":"Install TraeCode from the official download center, finish first-run setup, open a first project, and switch IDE mode and SOLO mode. The China site and the international site are separate surfaces.","frontmatter":{"title":"TraeCode tutorial","description":"Install TraeCode from the official download center, finish first-run setup, open a first project, and switch IDE mode and SOLO mode. The China site and the international site are separate surfaces.","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"products/trae/trae.md","filePath":"products/trae/trae.md","lastUpdated":1787107158000}'),n={name:"products/trae/trae.md"};function i(s,e,l,d,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="traecode-tutorial" tabindex="-1">TraeCode tutorial <a class="header-anchor" href="#traecode-tutorial" aria-label="Permalink to &quot;TraeCode tutorial&quot;">​</a></h1><blockquote><p>This page gets <strong>TraeCode</strong> installed and a first project open. Install paths are copied from the international <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a> and the China <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">getting started</a> page. Family boundaries: <a href="./">learning map</a>. OS / device limits / URLs: <a href="./trae-cheatsheet.html">cheatsheet</a>.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Goals</strong></p><ul><li>Tell the China site (<code>trae.cn</code> / <code>trae.com.cn</code>) from the international site (<code>trae.ai</code>)</li><li>Install the TraeCode desktop IDE from the official download page</li><li>Open a local folder, or clone a repo with the official steps</li><li>Switch <strong>IDE mode</strong> and <strong>SOLO mode</strong> at the top left</li></ul><p><strong>Non-goals</strong></p><ul><li>No TraeWork / Doubao / Coze / Ark tutorial</li><li>No invented <code>brew</code> / <code>npm</code> / curl install commands (official install is a downloadable package)</li><li>No TraeCode CLI (enterprise page: <strong>coming soon</strong>)</li><li>No Legacy quota table presented as current pricing</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>OS table from the international <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a> and China <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">getting started</a>:</p><table tabindex="0"><thead><tr><th>OS</th><th>Arch</th><th>Official versions / formats</th></tr></thead><tbody><tr><td>macOS</td><td>Apple Silicon, Intel</td><td><strong>12.0</strong> or later</td></tr><tr><td>Windows</td><td>64-bit (x64)</td><td><strong>Windows 10, Windows 11</strong></td></tr><tr><td>Linux</td><td>64-bit (x64), 64-bit (ARM64)</td><td><code>.deb</code>: Ubuntu 20.04, Debian 11; <code>.rpm</code>: Fedora 42, RHEL 9.x</td></tr></tbody></table><p>Account: a TRAE account. Login methods differ by surface; see section 3.</p><h2 id="_1-pick-a-surface-china-vs-international" tabindex="-1">1. Pick a surface: China vs international <a class="header-anchor" href="#_1-pick-a-surface-china-vs-international" aria-label="Permalink to &quot;1. Pick a surface: China vs international&quot;">​</a></h2><p>The international header includes a China-site link. These are not mirrors.</p><table tabindex="0"><thead><tr><th></th><th>International</th><th>China</th></tr></thead><tbody><tr><td>Marketing / download</td><td><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a> · <a href="https://www.trae.ai/download" target="_blank" rel="noreferrer">www.trae.ai/download</a></td><td><a href="https://www.trae.cn/" target="_blank" rel="noreferrer">www.trae.cn</a> · Quickstart links <a href="https://www.trae.com.cn" target="_blank" rel="noreferrer">www.trae.com.cn</a></td></tr><tr><td>Docs</td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai</a></td><td><a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">docs.trae.cn</a> (<a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer"><code>llms.txt</code></a>)</td></tr><tr><td>Device limit</td><td><strong>3</strong> (<a href="https://docs.trae.ai/ide/device-limit" target="_blank" rel="noreferrer">device-limit</a>)</td><td><strong>10</strong> (<a href="https://docs.trae.cn/ide_device-limit.md" target="_blank" rel="noreferrer">ide_device-limit.md</a>)</td></tr><tr><td>Login (official text)</td><td></td><td>Phone number, Douyin, Apple, Juejin (<a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">getting started</a>)</td></tr></tbody></table><p>Do not treat the two installers as the same product on one machine. Accounts, quota, and device counts are separate.</p><h2 id="_2-install-from-the-official-download" tabindex="-1">2. Install from the official download <a class="header-anchor" href="#_2-install-from-the-official-download" aria-label="Permalink to &quot;2. Install from the official download&quot;">​</a></h2><p>There is <strong>no</strong> official <code>curl | bash</code> or global npm package. The install entry is the download center.</p><h3 id="international" tabindex="-1">International <a class="header-anchor" href="#international" aria-label="Permalink to &quot;International&quot;">​</a></h3><ol><li>Open the <a href="https://www.trae.ai/download" target="_blank" rel="noreferrer">Download Center</a>.</li><li>Use the <strong>TraeCode</strong> block (copy: Your 10x AI Coding Engineer; <strong>Seamless switch between IDE and SOLO Mode</strong>). Do not download <strong>TraeWork</strong> from the same page.</li><li>Pick macOS (12.0+, including Intel), Windows 10/11, or <code>.deb</code> / <code>.rpm</code>.</li><li>Install and launch.</li></ol><p>International Quickstart: go to the official site, click <strong>Download IDE</strong> in the top right, download the package, install it.</p><p>macOS older than 12: the international Chinese Quickstart has said to download a build <strong>below 3.5.25</strong>. Use the Apple Silicon / Intel links on that page that day. This page does not invent extra URLs.</p><h3 id="china-site" tabindex="-1">China site <a class="header-anchor" href="#china-site" aria-label="Permalink to &quot;China site&quot;">​</a></h3><p>China <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">getting started</a>:</p><ol><li>Go to the <a href="https://www.trae.com.cn" target="_blank" rel="noreferrer">TRAE site</a>, click <strong>下载 IDE</strong> in the top right, download and install.</li><li>If macOS is below 12, download a TRAE IDE build <strong>below 3.3.25</strong>: <ul><li><a href="https://lf-cdn.trae.com.cn/obj/trae-com-cn/pkg/app/releases/stable/2.3.4283/darwin/Trae%20CN-darwin-arm64.dmg" target="_blank" rel="noreferrer">Apple Silicon</a></li><li><a href="https://lf-cdn.trae.com.cn/obj/trae-com-cn/pkg/app/releases/stable/2.3.4283/darwin/Trae%20CN-darwin-x64.dmg" target="_blank" rel="noreferrer">Intel</a></li></ul></li></ol><p>Do not merge China <code>3.3.25</code> with the international <code>3.5.25</code> note into one number.</p><h2 id="_3-first-run-setup-and-login" tabindex="-1">3. First-run setup and login <a class="header-anchor" href="#_3-first-run-setup-and-login" aria-label="Permalink to &quot;3. First-run setup and login&quot;">​</a></h2><p>Follow the wizard. China getting started lists:</p><ul><li>Theme and language</li><li>Import settings from <strong>VS Code or Cursor</strong></li><li>Add TRAE-related command-line tools</li><li>Sign in (China account types: section 1)</li></ul><p>International <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a> describes a full editor + Git + extension ecosystem. First-run wording follows the wizard of the build you downloaded.</p><p>「Add TRAE-related command-line tools」 is a wizard step. Official pages <strong>do not</strong> publish a binary name or a <code>brew install</code> string. This page does not invent one.</p><p>China extra step (same getting-started page): <strong>Settings &gt; Development environment</strong>, configure Node.js. Add a local SDK, or download the Node.js SDK bundled with TRAE IDE.</p><h2 id="_4-open-the-first-project" tabindex="-1">4. Open the first project <a class="header-anchor" href="#_4-open-the-first-project" aria-label="Permalink to &quot;4. Open the first project&quot;">​</a></h2><p>Three official entries (international Quickstart and China getting started match):</p><p><strong>Import a local folder</strong></p><ol><li>Click <strong>Open Folder</strong> in the center of the left panel, or <strong>Select project &gt; Open Folder</strong> at the top left.</li><li>Choose a local folder.</li></ol><p><strong>Clone from GitHub</strong></p><ol><li>Click <strong>Clone Git Repository</strong>, or <strong>Select project &gt; Clone Git Repository</strong>.</li><li>In the top panel, click <strong>Clone from GitHub</strong>.</li><li>Finish GitHub authorization, clone, and open.</li></ol><p><strong>Clone from a URL</strong></p><ol><li>Same <strong>Clone Git Repository</strong> entry.</li><li>Paste the Git URL, click <strong>Repository URL {URL}</strong>.</li><li>Follow the prompts, clone, and open.</li></ol><p>Once it is open, confirm the tree and terminal in IDE mode. Ask the agent for a read-only repo survey before edits. Review the diff. Do not turn on auto-run on the first pass.</p><h2 id="_5-switch-ide-mode-and-solo-mode" tabindex="-1">5. Switch IDE mode and SOLO mode <a class="header-anchor" href="#_5-switch-ide-mode-and-solo-mode" aria-label="Permalink to &quot;5. Switch IDE mode and SOLO mode&quot;">​</a></h2><p>Official: <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a>, <a href="https://docs.trae.ai/ide/solo-mode" target="_blank" rel="noreferrer">SOLO mode overview</a>, <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a>.</p><p>Use the mode switch at the <strong>top left</strong>.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Official behavior</th><th>Use when</th></tr></thead><tbody><tr><td><strong>IDE mode</strong></td><td>Editor, terminal, debug, extensions, source control; you control each step</td><td>Fine-grained edits in an existing repo</td></tr><tr><td><strong>SOLO mode</strong></td><td>AI leads planning through requirement understanding, generation, testing, and preview (the SOLO page also mentions deploy)</td><td>A vertical feature from natural language</td></tr></tbody></table><p>How to open SOLO: switch the mode to <strong>SOLO</strong>. Left to right: task panel, AI chat, tool panel (<a href="https://docs.trae.ai/ide/solo-mode" target="_blank" rel="noreferrer">SOLO mode overview</a>).</p><p>Input (SOLO page): natural language, voice, local file upload.</p><p>The SOLO page also lists SOLO Agent, multitasking, the tool panel (editor / docs / browser), Figma import, Supabase, deploy (Vercel is the example), AI services, payments (Stripe is the example), and the change diff. Follow those official child pages. This tutorial does not grow a second How-to.</p><p><strong>Do not</strong> install TraeWork because you want SOLO. TraeWork is a separate client. Official copy: it builds upon TraeCode SOLO mode.</p><h2 id="_6-agents-and-cue" tabindex="-1">6. Agents and CUE <a class="header-anchor" href="#_6-agents-and-cue" aria-label="Permalink to &quot;6. Agents and CUE&quot;">​</a></h2><p><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a> / <a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">CN same page</a>:</p><ul><li><strong>Agents</strong>: define tasks in natural language; search the codebase, plan steps, call tools. Custom agents can take prompts, MCP servers, and toolsets.</li><li><strong>CUE</strong>: completion, chained completion, multi-line edits, next-edit prediction and navigation; smart import and rename in <strong>Python, TypeScript, and Golang</strong>.</li><li><strong>Context</strong>: files, folders, snippets, terminal output, repos, document sets, web pages.</li><li><strong>Models</strong>: several built-in models; add custom models with an API key. The live list is the table on <a href="https://docs.trae.ai/ide/models" target="_blank" rel="noreferrer">models</a> that day. This page does not copy a roster that goes stale.</li></ul><p>The China What-is page also documents a 「速通」 boost when a model is queued. That paragraph is <strong>not</strong> on the international English What-is page as of 2026-08-19.</p><p>Safety (both What-is pages):</p><ul><li><strong>Privacy mode</strong>: chats, snippets, and AI outputs are not used for analysis, product optimization, or training. Codebase files stay on the local device.</li><li><strong>Sandbox</strong>: agent commands can run in a restricted environment with file-access controls and high-risk command blocking.</li></ul><h2 id="_7-device-limit" tabindex="-1">7. Device limit <a class="header-anchor" href="#_7-device-limit" aria-label="Permalink to &quot;7. Device limit&quot;">​</a></h2><p>Clients that count (same structure on both sites): <strong>TraeCode</strong>, <strong>TraeWork Desktop</strong>, <strong>TRAE mobile</strong>. <strong>TraeWork Web does not count</strong>. TraeCode + TraeWork Desktop on the same PC count as <strong>1</strong> device.</p><p>The cap differs:</p><ul><li>International: <strong>3</strong> (<a href="https://docs.trae.ai/ide/device-limit" target="_blank" rel="noreferrer">device-limit</a>)</li><li>China: <strong>10</strong> (<a href="https://docs.trae.cn/ide_device-limit.md" target="_blank" rel="noreferrer">ide_device-limit.md</a>)</li></ul><p>At the cap, login shows Device limit reached / <strong>设备数量已达上限</strong>. <strong>Sign out</strong> on a device you already use. Signing out a machine that has both TraeCode and TraeWork Desktop signed in signs both out.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ol><li><strong>Downloading TraeWork from the download page.</strong> This tutorial is TraeCode.</li><li><strong>Mixing China and international packages or accounts.</strong> Device caps and login providers differ.</li><li><strong>Treating SOLO mode as a separate TraeWork install.</strong> SOLO is the top-left switch inside TraeCode.</li><li><strong>Inventing a CLI install command.</strong> Official install is a package; CLI is coming soon on the enterprise page.</li><li><strong>Copying the Legacy quota table as current pricing.</strong> Use <a href="https://www.trae.ai/pricing" target="_blank" rel="noreferrer">pricing</a> and the current plans page.</li><li><strong>Using the other site&#39;s old-macOS fallback.</strong> China official direct links are Trae CN dmgs <strong>below 3.3.25</strong>.</li></ol><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Official URLs, OS, device limits → <a href="./trae-cheatsheet.html">cheatsheet</a></li><li>Family boundaries → <a href="./">learning map</a></li><li>Skills / MCP / custom agents → <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai</a> or <a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer">docs.trae.cn/llms.txt</a></li></ul>',63)])])}const b=t(n,[["render",i]]);export{u as __pageData,b as default};
